CREATE TABLE compliance_records(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kind text NOT NULL CHECK(kind IN('regulation','obligation','data_inventory','legal_basis','processor','transfer','risk','vulnerability','asvs','evidence','remediation','retention','policy','ai_processing','review')),
 external_key text UNIQUE,title text NOT NULL,status text NOT NULL DEFAULT 'not_assessed',data jsonb NOT NULL DEFAULT '{}',revision integer NOT NULL DEFAULT 1 CHECK(revision>0),created_by uuid REFERENCES users(id),updated_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX compliance_records_kind_status ON compliance_records(kind,status);
CREATE TABLE compliance_events(id bigserial PRIMARY KEY,record_id uuid,actor_id uuid REFERENCES users(id),event text NOT NULL,envelope jsonb NOT NULL,previous_hash text NOT NULL,entry_hash text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION protect_compliance_history() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Compliance evidence history is append-only'; END $$;
CREATE TRIGGER compliance_history_immutable BEFORE UPDATE OR DELETE ON compliance_events FOR EACH ROW EXECUTE FUNCTION protect_compliance_history();
CREATE TABLE compliance_incidents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,severity text NOT NULL CHECK(severity IN('low','medium','high','critical')),status text NOT NULL DEFAULT 'assessing',discovered_at timestamptz NOT NULL,aware_at timestamptz,certin_decision text NOT NULL DEFAULT 'undetermined',gdpr_decision text NOT NULL DEFAULT 'undetermined',uk_decision text NOT NULL DEFAULT 'undetermined',role text NOT NULL DEFAULT 'undetermined',data jsonb NOT NULL DEFAULT '{}',revision integer NOT NULL DEFAULT 1,created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE compliance_retention_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),policy_id uuid REFERENCES compliance_records(id),mode text NOT NULL CHECK(mode='dry_run'),candidate_count integer NOT NULL,detail jsonb NOT NULL,created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE compliance_notices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),dedupe_key text NOT NULL UNIQUE,kind text NOT NULL,resource_id text NOT NULL,message text NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE security_request_events(id bigserial PRIMARY KEY,method text NOT NULL,route text NOT NULL,status integer NOT NULL,duration_ms integer NOT NULL,address_hash text NOT NULL,address_encrypted text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX security_request_events_time ON security_request_events(created_at);
CREATE TRIGGER security_request_history_immutable BEFORE UPDATE OR DELETE ON security_request_events FOR EACH ROW EXECUTE FUNCTION protect_compliance_history();
